import{_ as t,c as o,o as s,ag as r}from"./chunks/framework.DZ_cNctr.js";const a="/docs/screenshots/svs-label-macro.png",m=JSON.parse('{"title":"Aperio SVS slides","description":"Open an Aperio SVS whole-slide file by its web address, an s3:// address or from your disk. JPEG and JPEG 2000 slides open in your browser with their stored resolutions. Nothing is converted or uploaded.","frontmatter":{"title":"Aperio SVS slides","search":false,"description":"Open an Aperio SVS whole-slide file by its web address, an s3:// address or from your disk. JPEG and JPEG 2000 slides open in your browser with their stored resolutions. Nothing is converted or uploaded."},"headers":[],"relativePath":"guides/aperio-svs.md","filePath":"guides/aperio-svs.md"}'),i={name:"guides/aperio-svs.md"};function n(d,e,l,h,p,c){return s(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="aperio-svs-slides" tabindex="-1">Aperio SVS slides <a class="header-anchor" href="#aperio-svs-slides" aria-label="Permalink to &quot;Aperio SVS slides&quot;">​</a></h1><p>Find Nuclei Viewer opens Aperio SVS files, the whole-slide format of Aperio scanners. Nothing is converted and nothing is uploaded. The viewer reads the file by byte range and decodes only the tiles you look at, so a large slide starts showing before it is downloaded.</p><p>Other formats the viewer opens are listed in <a href="./supported-formats.html">Supported Formats</a>. A sibling guide covers another slide and plate format: <a href="./zeiss-czi.html">Zeiss CZI Files</a>.</p><h2 id="opening-an-svs-from-the-web" tabindex="-1">Opening an SVS from the web <a class="header-anchor" href="#opening-an-svs-from-the-web" aria-label="Permalink to &quot;Opening an SVS from the web&quot;">​</a></h2><p>Click <strong>Open Image</strong> on the landing page, paste the address of the <code>.svs</code> file into the URL field and click <strong>Load from URL</strong>. An <code>https://</code> address and an <code>s3://</code> address both work.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-server.example.com/slides/slide.svs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>s3://your-bucket/your-folder/slide.svs</span></span></code></pre></div><p>The viewer reads the start of the file, then its directory of images, then the tiles. It never downloads the whole file to open it.</p><h2 id="opening-an-svs-from-disk" tabindex="-1">Opening an SVS from disk <a class="header-anchor" href="#opening-an-svs-from-disk" aria-label="Permalink to &quot;Opening an SVS from disk&quot;">​</a></h2><p>Drop the <code>.svs</code> file on the viewer. Or click <strong>Open Image</strong>, go to the <strong>Local Files</strong> tab and click <strong>Choose File</strong>. Opened files appear under <strong>Recent</strong>. Nothing leaves your computer.</p><p>Drop a folder that holds <code>.svs</code> files and the viewer says: &quot;Drop one SVS file to open it.&quot; Pick one file from the folder and drop that.</p><h2 id="what-opens" tabindex="-1">What opens <a class="header-anchor" href="#what-opens" aria-label="Permalink to &quot;What opens&quot;">​</a></h2><img width="3000" height="1900" src="`+a+'" alt="The Aperio slide CMU-1.svs open in the viewer: four pieces of H&amp;E stained tissue on the canvas, with the Label and Macro pictures under the file name in the right panel, and RGB contrast at 0 to 255" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><ul><li><strong>The slide.</strong> One image, in 2D, with its resolutions. Zooming out stays fast.</li><li><strong>Label and Macro.</strong> When the file holds the label photo or the macro photo, they appear under the title. Click one to enlarge it. A label may hold patient details. It is shown here and never saved or sent by the viewer. For a file on a server, your browser reads it from that server like the rest of the file.</li><li><strong>Compression.</strong> Slides with JPEG tiles and slides with JPEG 2000 tiles (the Aperio codes 33003 and 33005) open.</li></ul><h2 id="what-does-not-open-yet" tabindex="-1">What does not open yet <a class="header-anchor" href="#what-does-not-open-yet" aria-label="Permalink to &quot;What does not open yet&quot;">​</a></h2><p>A file the viewer cannot read is refused with a message that names the file and says why.</p><table tabindex="0"><thead><tr><th>Case</th><th>Message</th></tr></thead><tbody><tr><td>A file over 4 GB (BigTIFF)</td><td>This SVS file is larger than 4 GB. The viewer cannot read it yet.</td></tr><tr><td>Another compression</td><td>This SVS file uses a compression the viewer cannot read yet (LZW).</td></tr><tr><td>Not 8-bit RGB (grey, 16-bit or more than three channels)</td><td>This SVS file is not 8-bit RGB. The viewer cannot read it yet.</td></tr><tr><td>Not stored in tiles</td><td>This SVS file is not stored in tiles. The viewer cannot read it yet.</td></tr><tr><td>Not an Aperio file</td><td>This file is not an Aperio SVS file.</td></tr><tr><td>A damaged or incomplete file</td><td>This SVS file looks damaged or incomplete.</td></tr></tbody></table><p>A TIFF whose description does not mention Aperio is refused too. Other whole-slide formats open after conversion to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><h2 id="browsers" tabindex="-1">Browsers <a class="header-anchor" href="#browsers" aria-label="Permalink to &quot;Browsers&quot;">​</a></h2><p>An SVS is one file, so it opens from disk or by address in Chrome, Edge, Firefox and Safari alike.</p><p>Safari decodes JPEG tiles with its own decoder, so pixel values differ slightly from Chrome and Firefox. Use Chrome or Firefox for pixel measurements.</p><h2 id="hosts" tabindex="-1">Hosts <a class="header-anchor" href="#hosts" aria-label="Permalink to &quot;Hosts&quot;">​</a></h2><p>Opening by address needs a server that answers byte-range requests and allows them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For your own bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html">Remote URLs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the file and open it from your disk.</p><h2 id="public-svs-files-to-try" tabindex="-1">Public SVS files to try <a class="header-anchor" href="#public-svs-files-to-try" aria-label="Permalink to &quot;Public SVS files to try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> publishes test slides: <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Aperio/" target="_blank" rel="noreferrer">Aperio folder</a>. They are CC0, with JPEG and JPEG 2000 files. The server sends no CORS headers, so a browser cannot read them by address. Download a file and drop it on the viewer.</p><p>For other places to find public data, see <a href="./remote-urls.html">Remote URLs</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The viewer reads the file in your browser. Opening an SVS counts as one opened image of the kind &quot;Aperio SVS file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',28)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
